      const transactionNote = 'Booking Payment';

      // UPI deep link format
      const upiLink = `upi://pay?pa=${upiId}&pn=${encodeURIComponent(payeeName)}&am=${amount}&cu=INR&tn=${encodeURIComponent(transactionNote)}`;

      // Try to open UPI app, fallback to showing UPI ID
      window.location.href = upiLink;

      // Show processing state
      setProcessing(true);

      // Auto-success after 5 seconds (assuming user completes payment)
      setTimeout(() => {
        setProcessing(false);
        const userConfirm = window.confirm('Have you completed the payment? Click OK if payment is successful, Cancel to try again.');
